begin;
select no_plan();
insert into auth.users(id) values('89000000-0000-4000-8000-000000000001'),('89000000-0000-4000-8000-000000000002');
select public.assign_profile_role('89000000-0000-4000-8000-000000000001','editor');
select public.assign_profile_role('89000000-0000-4000-8000-000000000002','admin');
create function pg_temp.logo() returns jsonb language sql as $$ select jsonb_build_object('shopId','00000000-0000-4000-8000-000000000301','purpose','shop_logo','contentType','image/jpeg','sha256',repeat('a',64),'byteSize',200,'sourceRef','Synthetic logo original','rightsBasis','Test permission','creditText','Test photographer','altText','Test photo') $$;
create function pg_temp.output() returns jsonb language sql as $$ select jsonb_build_object('sha256',repeat('b',64),'byteSize',300,'width',20,'height',30) $$;
create function pg_temp.media(action text,payload jsonb default '{}',actor uuid default '89000000-0000-4000-8000-000000000001',env text default 'staging') returns jsonb language sql as $$ select public.media_upload_operation(actor,env,action,'89000000-0000-4000-8000-000000000010',payload) $$;
create temp table logo_before as select (select jsonb_agg(to_jsonb(a) order by id) from public.stamp_artwork_versions a) as art,
  (select jsonb_agg(to_jsonb(c) order by id) from public.stamp_collections c) as collections;
set local role service_role;
select is(pg_temp.media('initiate',pg_temp.logo())->>'contentType','image/jpeg','JPEG logo accepted');
select ok(pg_temp.media('read')->>'storageKey' is null,'no original-file storage key');
select throws_ok($$select pg_temp.media('finalize',pg_temp.output())$$,'22023','Upload mismatch','cannot finalize before output binding');
select throws_ok($$select pg_temp.media('prepare',pg_temp.output(),'89000000-0000-4000-8000-000000000002')$$,'P0002','Upload not found','other admin cannot bind output');
select throws_ok($$select pg_temp.media('prepare',pg_temp.output(),'89000000-0000-4000-8000-000000000001','production')$$,'P0002','Upload not found','wrong environment cannot bind output');
select throws_ok($$select pg_temp.media('prepare',pg_temp.output()||'{"width":1.5}')$$,'22023','Non-integer output','fractional dimensions rejected');
select throws_ok($$select pg_temp.media('prepare',pg_temp.output()||'{"contentType":"image/jpeg"}')$$,'22023','Invalid catalogue data','processed MIME cannot be supplied');
select throws_ok($$select pg_temp.media('prepare',pg_temp.output()||'{"width":1025}')$$,'23514',null,'output dimensions bounded');
select is(pg_temp.media('prepare',pg_temp.output())->>'storageKey','staging/media/89000000-0000-4000-8000-000000000010/v1/'||repeat('b',64)||'.png','key binds output checksum');
select is(pg_temp.media('read')->>'sha256',repeat('a',64),'original checksum retained separately');
select is((pg_temp.media('read')->'output'->>'byteSize')::int,300,'processed size differs from original');
select is(pg_temp.media('prepare',pg_temp.output())->>'status','pending','prepare retry stays private and pending');
select throws_ok($$select pg_temp.media('prepare',pg_temp.output()||jsonb_build_object('sha256',repeat('c',64)))$$,'23505','Output already bound; initiate again','retry cannot replace identity');
select throws_ok($$select pg_temp.media('finalize',pg_temp.output()||jsonb_build_object('sha256',repeat('a',64),'byteSize',200))$$,'22023','Upload mismatch','original checksum is not output checksum');
select throws_ok($$select pg_temp.media('finalize',pg_temp.output()||'{"height":31}')$$,'22023','Upload mismatch','independent final dimensions must match');
reset role;
select throws_ok($$update public.media_uploads set sha256=repeat('c',64) where id='89000000-0000-4000-8000-000000000010'$$,'42501','Upload identity is immutable','input identity immutable while pending');
select throws_ok($$update public.media_uploads set output_width=21 where id='89000000-0000-4000-8000-000000000010'$$,'42501','Upload identity is immutable','prepared output immutable');
select public.assign_profile_role('89000000-0000-4000-8000-000000000001','user');
set local role service_role;
select throws_ok($$select pg_temp.media('prepare',pg_temp.output())$$,'42501','Admin access denied','revocation blocks retry');
select throws_ok($$select pg_temp.media('finalize',pg_temp.output())$$,'42501','Admin access denied','revocation blocks finalization');
reset role;
select public.assign_profile_role('89000000-0000-4000-8000-000000000001','editor');
set local role authenticated;
select throws_ok($$select pg_temp.media('prepare',pg_temp.output())$$,'42501','permission denied for function media_upload_operation','browser cannot attest output');
set local role service_role;
select is(pg_temp.media('finalize',pg_temp.output())->>'status','validated','independent server attestation completes');
select is(pg_temp.media('finalize')->>'status','validated','completed retry is idempotent');
reset role;
select is((select count(*)::int from public.admin_audit_log where entity_type='media_uploads' and entity_id='89000000-0000-4000-8000-000000000010'),3,'initiation, output reservation and finalization each audited once');
select ok((select bool_and(actor_user_id='89000000-0000-4000-8000-000000000001' and actor_kind='account' and before_summary-array['fingerprint']='{}'::jsonb and after_summary-array['fingerprint']='{}'::jsonb) from public.admin_audit_log where entity_type='media_uploads' and entity_id='89000000-0000-4000-8000-000000000010'),'audit has actor and fingerprints, no private metadata');
select is((select content_type from public.media_uploads where id='89000000-0000-4000-8000-000000000010'),'image/jpeg','input MIME retained');
select is((select output_content_type from public.media_uploads where id='89000000-0000-4000-8000-000000000010'),'image/png','output MIME explicit');
select throws_ok($$update public.media_uploads set height=1 where id='89000000-0000-4000-8000-000000000010'$$,'42501','Validated upload is immutable','final receipt immutable');
select is((select jsonb_agg(to_jsonb(a) order by id) from public.stamp_artwork_versions a),(select art from logo_before),'artwork preserved');
select is((select jsonb_agg(to_jsonb(c) order by id) from public.stamp_collections c),(select collections from logo_before),'all impressions preserved');
select is((select count(*)::int from public.shop_images),0,'no attachment or publication');
-- A processed logo follows the same explicit private attachment/publication path.
create function pg_temp.logo_media(action text, target uuid default null, revision text default null)
returns jsonb language sql as $$ select public.shop_media_operation('89000000-0000-4000-8000-000000000002','staging','00000000-0000-4000-8000-000000000301',action,target,revision) $$;
select public.shop_media_operation('89000000-0000-4000-8000-000000000001','staging','00000000-0000-4000-8000-000000000301','attach','89000000-0000-4000-8000-000000000010');
select is((select kind from public.shop_images where upload_id='89000000-0000-4000-8000-000000000010'),'logo','processed JPEG attaches as logo');
select is(jsonb_array_length(pg_temp.logo_media('public_list')),0,'logo stays private after attachment');
select is((select storage_key from public.shop_images where upload_id='89000000-0000-4000-8000-000000000010'),pg_temp.media('read')->>'storageKey','attachment delivers processed PNG identity');
select pg_temp.logo_media('publish',id,md5(to_jsonb(i)::text)) from public.shop_images i where upload_id='89000000-0000-4000-8000-000000000010';
select is(pg_temp.logo_media('public_list')->0->>'kind','logo','explicitly published logo is public');
select pg_temp.logo_media('remove',id,md5(to_jsonb(i)::text)) from public.shop_images i where upload_id='89000000-0000-4000-8000-000000000010';
select is(jsonb_array_length(pg_temp.logo_media('public_list')),0,'removal withdraws the processed logo');
select is(pg_temp.media('read')->>'status','validated','removal retains immutable upload receipt');
select * from finish();
rollback;
